import os
os.environ['OPENBLAS_NUM_THREADS']='1'
import pathlib,json,csv,numpy as np
from export import collect,mat
ROOT=pathlib.Path(__file__).resolve().parent
def main():
 rows,bounds,records=collect();new=[d for d in rows if d['Jp']==.2375 and d['origin']=='NEW_DEFLATED_SOLVE'];table='| omega/J | S | F | hub weight | n/h intensity ratio | H residual/J |\n|---:|---:|---:|---:|---:|---:|\n'
 for d in new:table+=f"| {d['omega_J']:.12f} | {d['S']:g} | {d['reflection_parity']:+d} | {d['R_hh']:.12g} | {d['R_nn_over_R_hh']:.6g} | {d['H_residual']:.2e} |\n"
 text='# Stage 3 follow-up: weak-coupling spectral matrix\n\nAll data use N=27, Nup=14, M=Sz=1/2, J=1, source cell momentum (1/3,2/3), probe (0,1/3), and forward target (1/3,0). The reverse probe around the same source targets (1/3,1/3); the correct conjugate source at (2/3,1/3) with negative probe instead targets (2/3,0). These operations are distinguished in partner_source_validation.json. Fourier normalization is 1/sqrt(9)=1/3, with negative Fourier exponent and no extra 2pi spectral prefactor.\n\n'
 text+='## Additional converged poles at j=0.2375\n\n'+table+'\n'
 text+='The original two verified S=1/2 states are explicitly projected out of the initial seed and shifted by rank-one deflation in their respective reflection blocks. Subsequently verified states are added to the deflation set. Shift 64J exceeds the full bond spectral-width bound. ARPACK uses ncv=64 and tol=2e-12; every reported eigenpair passes a direct original-H residual, Casimir and orthogonality check. Both compatible reflection irreps carry seed weight and are searched. Probe-generated seeds include the allowed S=1/2 and 3/2 subspaces. This is not a proof of complete enumeration of all levels in either block.\n\n'
 text+='## Cumulative hub weight and explicit unresolved bounds\n\n| j | cutoff/J | verified weight | verified fraction | lower bound on total below cutoff | upper bound |\n|---:|---:|---:|---:|---:|---:|\n'
 for d in bounds:text+=f"| {d['Jp']:g} | {d['threshold_J']:g} | {d['verified_hub_weight_below']:.10f} | {d['verified_fraction_total']:.5%} | {d['conservative_total_lower_bound_minus_1e-8']:.10f} | {d['total_weight_below_upper_bound']:.10f} |\n"
 text+='\nVerified weights are independent pole residues. Bounds are inferred from positivity, not extra measured states. If unresolved moments are r0,r1,r2, the first-moment bound is W_unresolved(<T)>=max(0,r0-r1/T). The upper bound also uses bounded-support moment inequalities and the one-sided Chebyshev inequality when the remaining centroid exceeds the cutoff. A stronger bounded-band lower bound is max(0,r0-[(L+T)r1-r2]/(LT)), where L=sum_bonds(J_b)/4-E0 bounds every excitation from above. The polynomial x(L+T-x)/(LT) majorizes the tail indicator on [0,L]. Bounds are conditioned on the verified numerical ground state and operator moments, with a displayed 1e-8 roundoff margin; they are not formal interval-arithmetic eigenvalue certificates.\n\n'
 extra=sum(d['R_hh'] for d in new if d['omega_J']<.1);text+=f"Additional verified hub weight below 0.1J is {extra:.12f}; the original moment requirement was at least 0.1391992364980938. Remaining matrix moments, PSD checks, and partial sums are in spectral_remainders.json. No fictitious pole energy is assigned to unresolved weight.\n\n"
 text+='For an unresolved centroid mu>T, the one-sided Chebyshev (Cantelli) inequality additionally gives W_unresolved(<T)<=r0*variance/[variance+(mu-T)^2], where variance=r2/r0-mu^2. This makes the residual low-window weight much smaller than the total unresolved mass.\n\n'
 text+='| j | verified fraction of total hub M0 below 0.1J | upper bound on total fraction below 0.1J | guaranteed recovered fraction of window weight |\n|---:|---:|---:|---:|\n'
 remainder=json.loads((ROOT/'spectral_remainders.json').read_text())
 for item in [b for b in bounds if b['threshold_J']==.1]:
  j=item['Jp'];M0=remainder[str(j)]['exact_moments']['M0']['real'][2][2];v=item['verified_hub_weight_below'];upper=item['conservative_total_upper_bound_plus_1e-8'];text+=f"| {j:g} | {v/M0:.6%} | {upper/M0:.6%} | {v/upper:.6%} |\n"
 text+='\nThis bounds the missing hub weight in the requested window; it is not a proof that every individual eigenstate in that window is listed.\n\n'
 text+='## Controlled coupling comparison\n\nAll energies and full complex 3x3 residues are exported in verified_poles.csv and complex_residues.csv, including energies divided by Jprime squared. Branches are matched by spin/reflection labels and actual eigenvector overlaps, not sorted index. matched_branch_overlaps.json records the evidence; only matched available states are compared. The earlier two S=1/2 branch overlaps exceed 0.9986. Missing counterpart states remain unresolved.\n\n'
 text+='| j | omega/J | S | F | hub weight | rim Neel weight | Re R_nh | Im R_nh |\n|---:|---:|---:|---:|---:|---:|---:|---:|\n'
 for d in rows:text+=f"| {d['Jp']:g} | {d['omega_J']:.12f} | {d['S']:g} | {d['reflection_parity']:+d} | {d['R_hh']:.8g} | {d['R_nn']:.8g} | {d['R_nh_real']:.8g} | {d['R_nh_imag']:.8g} |\n"
 text+='\nThe bright newly resolved hub modes have finite complex rim cross residues, while their rim Neel intensities remain roughly one percent of hub intensities at 0.2375. A much weaker pole can have a larger relative rim fraction without carrying appreciable absolute rim weight. These are coupled-system spectra, not an independently extracted irreducible hub susceptibility. The matched very-soft S=1/2 energies do not collapse exactly in Jprime-squared units. The nearly unchanged integrated hub M0 and increased M1 do not by themselves specify individual pole shifts. The very small unresolved high-energy fraction nevertheless carries much of M1 and M2; its centroid is an energy mean, not an extra pole.\n\n'
 text+='## Validation and status\n\nM0=B-dagger B, M1=B-dagger(H-E0)B, and M2=[(H-E0)B]-dagger[(H-E0)B] are computed directly. The full 4x4 n,m,h,Phi moments are provided in four_channel_exact_moments.json; Phi is a known momentum-dependent linear combination of n and m, so this four-channel matrix is rank deficient by construction. Zeroth moments are independently checked against real-space Gzz and symmetrized first moments against the bond f-sum. Fixed-M zz quantities are used throughout, not scalar-dot/3 for arbitrary spin. The target has no ground-multiplet elastic contribution. The 0.2 original-H and total-spin source check is in matched_j0.2.json.\n\n'
 text+='The referenced stage3_cross_moments_direct_27spin.csv was not supplied in the available attachments. We compare all supplied diagonal benchmarks and independently reconstruct the full cross-moment matrices instead. The supplied 0.2 hub M0,M1,M2 agree to better than 6e-15. Previously verified 0.2375 moments are reused. Small-complex-sector tests compare physically deflated eigenpairs with a dense eigenspectrum and validate the tail-bound polynomial. Full residue, remainder and block-Hankel positivity are checked to numerical precision.\n\n'
 text+='| Data product | Status | Use |\n|---|---|---|\n| verified_poles.csv | Direct original-H and S-squared checked | Physical pole energies/residues |\n| Prior 72-dimensional quadrature | Approximate nodes, not eigenpairs | Prior moment-complete visualization only; never a deflation input |\n| spectral_remainders.json | Exact operator moments minus verified sums | Remaining spectral mass and positivity bounds |\n\n'
 text+='CPU quota is two cores and RAM cap 8 GiB. Each new solve records H calls, elapsed solve seconds, ncv and process high-water RSS in its JSON; setup, shared-source preparation and matched-comparison timing are separately scoped. Per-process wall times overlap and must not be added as end-to-end elapsed time. Each iterative H callback has a 1200-second cutoff; final verification and checkpoint I/O may extend the recorded elapsed time beyond it; a timeout record is never a converged eigenvalue. No complete spectrum is claimed. Finite-size stick spectra and cumulative-weight plots use no broadening and imply no thermodynamic magnon damping, velocity, phase transition or self-energy.\n\n'
 costfile=ROOT/'computational_costs.json'
 if costfile.exists():
  cost=json.loads(costfile.read_text());text+=f"Measured accepted new work: {cost['new_verified_eigenpairs']} eigenpairs, {cost['iterative_H_calls']} iterative H calls, {cost['sum_completed_solve_wall_seconds']/60:.2f} summed solve-wall minutes (overlapping jobs), peak process RSS {cost['maximum_process_peak_RSS_MiB']:.1f} MiB. These sums exclude source preparation, final validation and the stopped duplicate worker.\n\n"
 text+='Unresolved moment ledger (centroids are means, not additional poles):\n\n| j | unresolved fraction of hub M0 | unresolved fraction of hub M1 | unresolved centroid / J |\n|---:|---:|---:|---:|\n'
 for j in [.2,.2375]:
  x=remainder[str(j)];r0=x['unresolved_moments']['M0']['real'][2][2];r1=x['unresolved_moments']['M1']['real'][2][2];m0=x['exact_moments']['M0']['real'][2][2];m1=x['exact_moments']['M1']['real'][2][2];text+=f"| {j:g} | {r0/m0:.6%} | {r1/m1:.6%} | {r1/r0:.9f} |\n"
 text+='\n'
 text+='Next targeted run, if needed: deflate the delivered verified vectors in both reflection sectors, use separate Casimir-projected S=1/2 and 3/2 starts, and stop according to the explicit residual weight bounds rather than a chosen count of Ritz values. Match newly found states across couplings using their delivered vectors and quantum labels.\n'
 (ROOT/'report.md').write_text(text)
 os.environ.setdefault('MPLCONFIGDIR',str(ROOT/'.mpl'));os.environ.setdefault('XDG_CACHE_HOME',str(ROOT/'.cache'))
 import matplotlib;matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 fig,ax=plt.subplots(figsize=(8,4.6),layout='constrained')
 for j,color in [(.2,'tab:blue'),(.2375,'tab:orange')]:
  data=[d for d in rows if d['Jp']==j and d['omega_J']<.1];b=[x for x in bounds if x['Jp']==j];M0=json.loads((ROOT/'spectral_remainders.json').read_text())[str(j)]['exact_moments']['M0']['real'][2][2]
  xs=[0]+[d['omega_J'] for d in data]+[.1];ys=[0]+np.cumsum([d['R_hh'] for d in data]).tolist()+[sum(d['R_hh'] for d in data)];ax.step(xs,np.array(ys)/M0,where='post',label=f'j={j:g}: verified',color=color)
  for t in b:ax.plot([t['threshold_J']]*2,[t['conservative_total_lower_bound_minus_1e-8']/M0,t['total_weight_below_upper_bound']/M0],color=color,alpha=.6,linewidth=4)
 ax.set(xlabel='Excitation cutoff / J',ylabel='Fraction of total hub longitudinal weight',title='Verified cumulative weight; vertical segments: moment bounds',ylim=(0,1.03));ax.grid(alpha=.25);ax.legend();fig.savefig(ROOT/'cumulative_hub_weight.png',dpi=170);plt.close(fig)
 print(table)
if __name__=='__main__':main()
